using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
namespace FocusGrowth {
public static class ContinuousTests {
 static int passed;static readonly System.Collections.Generic.List<object> rows=new System.Collections.Generic.List<object>();
 static void Test(string name,Action f){try{f();rows.Add(new{name,pass=true});passed++;}catch{rows.Add(new{name,pass=false});}}
 static void Require(bool b){Schema.Require(b,"test_failed");}static void Reject(Action f){try{f();}catch(Fault){return;}throw new Exception();}
 static Dictionary<string,object> Full(){return J.Copy(PreparationTests.Full());}
 static Dictionary<string,object> Attach(Dictionary<string,object> db,bool prod,string id="client-test"){return new Dictionary<string,object>{{"clientId",id},{"raw",LocalJson.Dump(db)},{"source",new Dictionary<string,object>{{"origin",Bridge.Pages},{"pathname","/focus-growth/"},{"storageKey",prod?"start-workbench-v1":"start-workbench-sync-test-v04"}}}};}
 static Dictionary<string,object> Op(Dictionary<string,object> b,Dictionary<string,object> d,string id="op-test"){return new Dictionary<string,object>{{"clientId","client-test"},{"base",b},{"desired",d},{"operationId",id}};}
 static ContinuousController Make(string dir,FakeCloud cloud,bool prod,Func<bool> grant){return new ContinuousController(prod,"device-test",cloud,new Disk(dir),new LocalVault(Path.Combine(dir,"backups")),grant);}
 public static void Run(string root){passed=0;rows.Clear();string dir=Path.GetFullPath(Path.Combine(root,"..","..","work","v04","tests-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(dir);
 Test("production_default_read_only_and_pause",()=>{var cloud=new FakeCloud();cloud.Data.State=PreparationModel.Project(Full());cloud.Data.State["revision"]=1;cloud.Data.State["initialized"]=true;var c=Make(Path.Combine(dir,"prod"),cloud,true,()=>false);c.Tick(true);Require(!c.Enabled&&!c.Authorized&&cloud.Writes==0);c.Attach(Attach(Full(),true),Bridge.Pages);Reject(()=>c.Resume("client-test"));var b=J.Copy(cloud.Data.State);var d=J.Copy(b);J.Obj(J.Arr(d["tasks"])[0])["name"]="synthetic changed";Reject(()=>c.Queue(Op(b,d),false));Require(cloud.Writes==0);c.Pause();});
 Test("synthetic_enable_pause_preserves_queue",()=>{var cloud=new FakeCloud();var c=Make(Path.Combine(dir,"pause"),cloud,false,()=>false);c.Tick(true);c.Attach(Attach(Full(),false),Bridge.Pages);c.Resume("client-test");var d=PreparationModel.Project(Full());c.Queue(Op(Schema.Empty(),d),false);c.Pause();c.Tick(true);Require(cloud.Writes==0&&(bool)c.View()["pending"]);c.Resume("client-test");c.Tick(true);Require(cloud.Writes==1&&!(bool)c.View()["pending"]);});
 Test("offline_queue_survives_process_restart_and_retries_once",()=>{var cloud=new FakeCloud();string p=Path.Combine(dir,"offline");var c=Make(p,cloud,false,()=>false);c.Attach(Attach(Full(),false),Bridge.Pages);c.Resume("client-test");c.Queue(Op(Schema.Empty(),PreparationModel.Project(Full())),false);cloud.Offline=true;c.Tick(true);Require((bool)c.View()["pending"]&&cloud.Writes==0);c=Make(p,cloud,false,()=>false);Require(c.Enabled);cloud.Offline=false;c.Tick(true);Require(cloud.Writes==1);c.Attach(Attach(Full(),false),Bridge.Pages);c.Resume("client-test");c.Tick(true);c.Tick(true);Require(cloud.Writes==1&&!(bool)c.View()["pending"]);});
 Test("revoked_authorization_never_flushes_pending",()=>{bool allow=true;var cloud=new FakeCloud();var c=Make(Path.Combine(dir,"revoke"),cloud,true,()=>allow);c.Attach(Attach(Full(),true),Bridge.Pages);c.Resume("client-test");c.Queue(Op(Schema.Empty(),PreparationModel.Project(Full())),false);allow=false;c.Tick(true);Require(!c.Enabled&&cloud.Writes==0&&(bool)c.View()["pending"]);});
 Test("source_profile_and_demo_checks",()=>{var c=Make(Path.Combine(dir,"source"),new FakeCloud(),true,()=>false);Reject(()=>c.Attach(Attach(Full(),true),"http://127.0.0.1:18421"));var req=Attach(Full(),true);J.Obj(req["source"])["storageKey"]="start-workbench-sync-test-v04";Reject(()=>c.Attach(req,Bridge.Pages));var demo=Full();demo["demo"]=true;Reject(()=>c.Attach(Attach(demo,true),Bridge.Pages));});
 Test("single_workspace_lease_and_explicit_release",()=>{var c=Make(Path.Combine(dir,"lease"),new FakeCloud(),false,()=>false);c.Attach(Attach(Full(),false),Bridge.Pages);Reject(()=>c.Attach(Attach(Full(),false,"other-client"),Bridge.Pages));Reject(()=>c.Resume("other-client"));c.Release();c.Attach(Attach(Full(),false,"other-client"),Bridge.Pages);c.Resume("other-client");Require(c.Enabled);});
 Test("checkpoint_encrypted_and_full_restore",()=>{var c=Make(Path.Combine(dir,"backup"),new FakeCloud(),false,()=>false);c.Attach(Attach(Full(),false),Bridge.Pages);var checkpoint=J.Obj(c.Checkpoint(new Dictionary<string,object>{{"clientId","client-test"},{"raw",LocalJson.Dump(Full())}}));byte[] restored=LocalVault.Read(checkpoint);PreparationModel.ValidateFull(J.Obj(LocalJson.Parse(Encoding.UTF8.GetString(restored))));Require(!Encoding.UTF8.GetString(File.ReadAllBytes((string)checkpoint["path"])).Contains("LOCAL_PRIVATE_TEST_CANARY"));});
 Test("conflict_requires_field_resolution_no_silent_write",()=>{var cloud=new FakeCloud();var initial=PreparationModel.Project(Full());cloud.Data=new Snapshot{State=J.Copy(initial),Sha="base"};var c=Make(Path.Combine(dir,"conflict"),cloud,false,()=>false);c.Tick(true);c.Attach(Attach(Full(),false),Bridge.Pages);c.Resume("client-test");var local=J.Copy(initial);J.Obj(J.Arr(local["tasks"])[0])["name"]="local";J.Obj(J.Arr(cloud.Data.State["tasks"])[0])["name"]="remote";cloud.Data.Sha="remote";c.Queue(Op(initial,local),false);c.Tick(true);Require(cloud.Writes==0&&J.Arr(c.View()["conflicts"]).Count==1);var remote=J.Copy(cloud.Data.State);var chosen=J.Copy(remote);J.Obj(J.Arr(chosen["tasks"])[0])["name"]="chosen";var op=Op(remote,chosen,"resolved-op");op["previousOperationId"]="op-test";c.Queue(op,true);c.Tick(true);Require(cloud.Writes==1&&J.Str(J.Obj(J.Arr(cloud.Data.State["tasks"])[0])["name"])=="chosen");});
 Test("duplicate_operation_has_no_second_commit",()=>{var cloud=new FakeCloud();var c=Make(Path.Combine(dir,"duplicate"),cloud,false,()=>false);c.Attach(Attach(Full(),false),Bridge.Pages);c.Resume("client-test");var op=Op(Schema.Empty(),PreparationModel.Project(Full()));c.Queue(op,false);c.Tick(true);c.Queue(op,false);c.Tick(true);Require(cloud.Writes==1);});
 Test("production_rejects_test_network_control",()=>{var c=Make(Path.Combine(dir,"network"),new FakeCloud(),true,()=>false);c.NetworkControl=b=>{};Reject(()=>c.SetNetwork(true));});
 Test("authorization_is_permanent_scoped_encrypted_and_device_bound",()=>{string p=Path.Combine(dir,"grant");var grant=new ContinuousGrant(p,"device-one");Require(!grant.Valid);grant.Issue("SYNTHETIC consent reference only",new string('a',40),new string('b',64));Require(grant.Valid&&!new ContinuousGrant(p,"device-two").Valid);Require(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(p,"continuous-authorization.dat"))).Contains("SYNTHETIC consent"));});
 Test("semantic_rows_are_order_independent",()=>{var a=PreparationModel.Project(Full());var b=J.Copy(a);var item=J.Copy(J.Arr(a["tasks"])[0]);item["id"]="another";J.Arr(a["tasks"]);a["tasks"]=new[]{J.Arr(a["tasks"])[0],item};b["tasks"]=new[]{item,J.Arr(a["tasks"])[0]};Require(Schema.SameData(a,b));});
 Test("unknown_schema_pauses_without_losing_queue",()=>{var cloud=new FakeCloud();var c=Make(Path.Combine(dir,"schema"),cloud,false,()=>false);c.Attach(Attach(Full(),false),Bridge.Pages);c.Resume("client-test");c.Queue(Op(Schema.Empty(),PreparationModel.Project(Full())),false);cloud.Data.State["schemaVersion"]=2;c.Tick(true);Require(!c.Enabled&&(bool)c.View()["pending"]&&cloud.Writes==0);});
 var httpCloud=new FakeCloud();var http=Make(Path.Combine(dir,"http"),httpCloud,true,()=>false);httpCloud.Data.State=PreparationModel.Project(Full());httpCloud.Data.State["initialized"]=true;httpCloud.Data.State["revision"]=1;http.Tick(true);http.Attach(Attach(Full(),true),Bridge.Pages);var pairing=new Pairing();string token=pairing.Pair(pairing.Code,Bridge.Pages,_=>true);
 using(var bridge=new ContinuousBridge(http,pairing,Path.Combine(root,"web"),_=>false)){bridge.Start();
  Func<string,string,string,string,Tuple<int,string,string>> call=(method,route,origin,auth)=>{using(var client=new System.Net.Http.HttpClient(new System.Net.Http.HttpClientHandler{UseProxy=false})){client.Timeout=TimeSpan.FromSeconds(5);using(var req=new System.Net.Http.HttpRequestMessage(new System.Net.Http.HttpMethod(method),"http://127.0.0.1:18421"+route)){if(origin!=null)req.Headers.Add("Origin",origin);req.Headers.Add("X-FG-Client","1");if(auth!=null)req.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",auth);if(method=="POST")req.Content=new System.Net.Http.StringContent(route=="/v1/enable"?"{\"clientId\":\"client-test\"}":route=="/v1/test/network"?"{\"offline\":true}":"{}",Encoding.UTF8,"application/json");using(var response=client.SendAsync(req).GetAwaiter().GetResult()){string cors=response.Headers.Contains("Access-Control-Allow-Origin")?response.Headers.GetValues("Access-Control-Allow-Origin").First():null;return Tuple.Create((int)response.StatusCode,response.Content.ReadAsStringAsync().GetAwaiter().GetResult(),cors);}}}};
  Test("http_health_has_no_task_or_credentials",()=>{var r=call("GET","/health",null,null);Require(r.Item1==200&&!r.Item2.Contains("tasks")&&!r.Item2.Contains("session")&&J.Obj(J.Parse(r.Item2)).Count==4);});
  Test("http_unauthenticated_state_rejected",()=>Require(call("GET","/v1/state",Bridge.Pages,null).Item1==401));
  Test("http_hostile_origin_rejected_without_cors",()=>{var r=call("GET","/v1/state","https://evil.example",token);Require(r.Item1==400&&r.Item3==null);});
  Test("http_paired_production_enable_denied_without_grant",()=>Require(call("POST","/v1/enable",Bridge.Pages,token).Item1==403&&httpCloud.Writes==0));
  Test("http_paired_state_read_is_safe",()=>{var r=call("GET","/v1/state",Bridge.Pages,token);var v=J.Obj(J.Parse(r.Item2));Require(r.Item1==200&&r.Item3==Bridge.Pages&&(bool)v["productionLocked"]&&!(bool)v["enabled"]&&!r.Item2.Contains("LOCAL_PRIVATE_TEST_CANARY"));});
  Test("http_production_cannot_use_synthetic_network_control",()=>Require(call("POST","/v1/test/network",Bridge.Pages,token).Item1==403));
  pairing.ExpireForTest();Test("http_expired_session_rejected",()=>Require(call("GET","/v1/state",Bridge.Pages,token).Item1==401));
 }
 File.WriteAllText(Path.Combine(root,"continuous-test-results.json"),J.Dump(new{passed,total=rows.Count,tests=rows}));Environment.ExitCode=passed==rows.Count?0:1;
 }
}
}
